pub fn count_file(lang_name: &str, content: &str) -> Stats {
    if lang_name == "Jupyter Notebooks" {
        return Stats::default();
    }
    let def = match get_lang_def(lang_name) {
        Some(d) => d,
        None => return Stats::default(),
    };
    if def.is_all_comments {
        let mut stats = Stats::default();
        for line in content.lines() {
            if line.trim().is_empty() {
                stats.blanks += 1;
            } else {
                stats.comments += 1;
            }
        }
        return stats;
    }
    if def.is_markdown {
        return count_markdown(content, false);
    }
    if def.is_unreal_markdown {
        return count_markdown(content, true);
    }
    if def.is_rust {
        return count_rust(content);
    }
    if def.is_html_like {
        return count_html_like(lang_name, content);
    }
    if def.is_fortran {
        return count_fortran(def, content);
    }
    count_generic(def, content)
}

