fn is_escaped(line: &str, pos: usize) -> bool {
    let bytes = line.as_bytes();
    if pos == 0 { return false; }
    let mut count = 0;
    let mut j = pos;
    while j > 0 {
        j -= 1;
        if bytes[j] == b'\\' {
            count += 1;
        } else {
            break;
        }
    }
    count % 2 == 1
}

