fn is_tag_open(lower_trimmed: &str, tag: &str) -> bool {
    if !lower_trimmed.starts_with(tag) {
        return false;
    }
    if lower_trimmed.len() == tag.len() {
        return true;
    }
    let next = lower_trimmed.as_bytes()[tag.len()];
    next == b' ' || next == b'\t' || next == b'\r' || next == b'>' || next == b'/'
}

